export const dictionaries = { de, en, fr, ar } as const;
export type Language = keyof typeof dictionaries;
export const SUPPORTED_LANGUAGES: readonly Language[] = ["de", "en", "fr", "ar"];
export const DEFAULT_LANGUAGE: Language = "de";

/** Native-language display name for the picker (language-agnostic). */
export const LANGUAGE_META: Record<Language, { code: string; native: string; dir: "ltr" | "rtl" }> = {
  de: { code: "de", native: "Deutsch", dir: "ltr" },
  en: { code: "en", native: "English", dir: "ltr" },
  fr: { code: "fr", native: "Français", dir: "ltr" },
  ar: { code: "ar", native: "العربية", dir: "rtl" },
};
